import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64
// Register-blocked 3D convolution: each CTA computes an 8x8x16 output tile
// (1024 outputs, 256 threads, 4 adjacent outputs per thread along W).
// Input tile staged in smem: 3 x 10 x 10 x 18 floats (21600 bytes),
// weights staged at smem byte offset 21600 (81 floats). The 3*3*3*3
// reduction is fully unrolled with immediate shared-memory offsets and a
// 6-tap sliding window of input values reused across the 4 per-thread
// outputs (register blocking): shared-memory load traffic per output is
// roughly halved for inputs and quartered for weights versus the
// one-output-per-thread version.
.extern .shared .align 4 .b8 s_in[];
.visible .entry conv3d_f32_sm89(
    .param .u64 p_in,
    .param .u64 p_w,
    .param .u64 p_out
)
{
    .reg .pred %p0, %p1, %p2, %p3;
    .reg .u32 %r_bid, %r_tid, %r_tmp, %r_tmp2;
    .reg .u32 %r_n, %r_rem, %r_oc, %r_rem2, %r_tod, %r_rem3, %r_toh, %r_tow;
    .reg .u32 %r_id0, %r_ih0, %r_iw0;
    .reg .u32 %r_i, %r_ic, %r_kd, %r_kh, %r_kw, %r_id, %r_ih, %r_iw;
    .reg .u32 %r_od, %r_oh, %r_ow, %r_kdl, %r_khl, %r_kwl;
    .reg .u32 %r_sbase, %r_soff, %r_inA;
    .reg .b64 %rd_in, %rd_w, %rd_out, %rd_off, %rd_addr, %rd_sgen;
    .reg .f32 %f_acc0, %f_acc1, %f_acc2, %f_acc3;
    .reg .f32 %f_x0, %f_x1, %f_x2, %f_x3, %f_x4, %f_x5;
    .reg .f32 %f_b0, %f_b1, %f_b2, %f_g;
    ld.param.u64 %rd_in, [p_in];
    ld.param.u64 %rd_w, [p_w];
    ld.param.u64 %rd_out, [p_out];
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_tid, %tid.x;
    mov.u64 %rd_sgen, s_in;
    cvt.u32.u64 %r_sbase, %rd_sgen;
    // decompose block id -> (n, oc, tod, toh, tow)
    // tiles per (n,oc) = 8*8*4 = 256, per n = 64*256 = 16384
    div.u32 %r_n, %r_bid, 16384;
    mul.lo.u32 %r_tmp, %r_n, 16384;
    sub.u32 %r_rem, %r_bid, %r_tmp;
    div.u32 %r_oc, %r_rem, 256;
    mul.lo.u32 %r_tmp, %r_oc, 256;
    sub.u32 %r_rem2, %r_rem, %r_tmp;
    div.u32 %r_tod, %r_rem2, 32;
    mul.lo.u32 %r_tmp, %r_tod, 32;
    sub.u32 %r_rem3, %r_rem2, %r_tmp;
    div.u32 %r_toh, %r_rem3, 4;
    mul.lo.u32 %r_tmp, %r_toh, 4;
    sub.u32 %r_tow, %r_rem3, %r_tmp;
    shl.b32 %r_id0, %r_tod, 3;
    shl.b32 %r_ih0, %r_toh, 3;
    shl.b32 %r_iw0, %r_tow, 4;
    // ---- stage weights (81 floats) at smem byte offset 21600 ----
    setp.lt.u32 %p0, %r_tid, 81;
    @!%p0 bra $Lwt_done;
    mul.lo.u32 %r_tmp, %r_oc, 81;
    add.u32 %r_tmp, %r_tmp, %r_tid;
    cvt.u64.u32 %rd_off, %r_tmp;
    mul.lo.u64 %rd_off, %rd_off, 4;
    add.u64 %rd_addr, %rd_w, %rd_off;
    ld.global.f32 %f_g, [%rd_addr];
    mul.lo.u32 %r_tmp, %r_tid, 4;
    add.u32 %r_soff, %r_sbase, %r_tmp;
    st.shared.f32 [%r_soff+21600], %f_g;
$Lwt_done:
    // ---- cooperative staging of input tile: 3*10*10*18 = 5400 floats ----
    mov.u32 %r_i, %r_tid;
$Liloop:
    setp.lt.u32 %p0, %r_i, 5400;
    @!%p0 bra $Lsync;
    div.u32 %r_ic, %r_i, 1800;
    mul.lo.u32 %r_tmp, %r_ic, 1800;
    sub.u32 %r_rem, %r_i, %r_tmp;
    div.u32 %r_kd, %r_rem, 180;
    mul.lo.u32 %r_tmp, %r_kd, 180;
    sub.u32 %r_rem2, %r_rem, %r_tmp;
    div.u32 %r_kh, %r_rem2, 18;
    mul.lo.u32 %r_tmp, %r_kh, 18;
    sub.u32 %r_kw, %r_rem2, %r_tmp;
    add.u32 %r_id, %r_id0, %r_kd;
    add.u32 %r_ih, %r_ih0, %r_kh;
    add.u32 %r_iw, %r_iw0, %r_kw;
    mov.f32 %f_g, 0f00000000;
    setp.lt.u32 %p1, %r_id, 64;
    setp.lt.u32 %p2, %r_ih, 64;
    setp.lt.u32 %p3, %r_iw, 64;
    and.pred %p1, %p1, %p2;
    and.pred %p1, %p1, %p3;
    @!%p1 bra $Lstore_smem;
    mul.lo.u32 %r_tmp, %r_n, 3;
    add.u32 %r_tmp, %r_tmp, %r_ic;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_id;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_ih;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_iw;
    cvt.u64.u32 %rd_off, %r_tmp;
    mul.lo.u64 %rd_off, %rd_off, 4;
    add.u64 %rd_addr, %rd_in, %rd_off;
    ld.global.f32 %f_g, [%rd_addr];
$Lstore_smem:
    mul.lo.u32 %r_tmp, %r_i, 4;
    add.u32 %r_soff, %r_sbase, %r_tmp;
    st.shared.f32 [%r_soff], %f_g;
    add.u32 %r_i, %r_i, 256;
    bra $Liloop;
$Lsync:
    bar.sync 0;
    // ---- per-thread output coordinates (4 adjacent outputs along W) ----
    shr.u32 %r_kdl, %r_tid, 5;
    shr.u32 %r_tmp, %r_tid, 2;
    and.b32 %r_khl, %r_tmp, 7;
    and.b32 %r_kwl, %r_tid, 3;
    add.u32 %r_od, %r_id0, %r_kdl;
    add.u32 %r_oh, %r_ih0, %r_khl;
    shl.b32 %r_tmp, %r_kwl, 2;
    add.u32 %r_ow, %r_iw0, %r_tmp;
    setp.lt.u32 %p1, %r_od, 62;
    setp.lt.u32 %p2, %r_oh, 62;
    and.pred %p1, %p1, %p2;
    @!%p1 bra $Lret;
    // input smem base float index: (kdl*10 + khl)*18 + kwl*4
    mul.lo.u32 %r_tmp, %r_kdl, 10;
    add.u32 %r_tmp, %r_tmp, %r_khl;
    mul.lo.u32 %r_tmp, %r_tmp, 18;
    shl.b32 %r_tmp2, %r_kwl, 2;
    add.u32 %r_tmp, %r_tmp, %r_tmp2;
    shl.b32 %r_tmp, %r_tmp, 2;
    add.u32 %r_inA, %r_sbase, %r_tmp;
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.f32 %f_acc2, 0f00000000;
    mov.f32 %f_acc3, 0f00000000;
    // ---- fully unrolled accumulation: ic(3) x kd(3) x kh(3), kw unrolled ----
    // in-offset stride floats: ic=1800, kd=180, kh=18 (x4 for bytes)
    // weight-offset stride floats: ic=27, kd=9, kh=3 (x4 for bytes, +21600)
    // ic=0 kd=0 kh=0
    ld.shared.f32 %f_x0, [%r_inA+0];
    ld.shared.f32 %f_x1, [%r_inA+4];
    ld.shared.f32 %f_x2, [%r_inA+8];
    ld.shared.f32 %f_x3, [%r_inA+12];
    ld.shared.f32 %f_x4, [%r_inA+16];
    ld.shared.f32 %f_x5, [%r_inA+20];
    ld.shared.f32 %f_b0, [%r_sbase+21600];
    ld.shared.f32 %f_b1, [%r_sbase+21604];
    ld.shared.f32 %f_b2, [%r_sbase+21608];
    fma.rn.f32 %f_acc0, %f_x0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x1, %f_b1, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x2, %f_b2, %f_acc0;
    fma.rn.f32 %f_acc1, %f_x1, %f_b0, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x2, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x3, %f_b2, %f_acc1;
    fma.rn.f32 %f_acc2, %f_x2, %f_b0, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x3, %f_b1, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x4, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_x3, %f_b0, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x4, %f_b1, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x5, %f_b2, %f_acc3;
    // ic=0 kd=0 kh=1
    ld.shared.f32 %f_x0, [%r_inA+72];
    ld.shared.f32 %f_x1, [%r_inA+76];
    ld.shared.f32 %f_x2, [%r_inA+80];
    ld.shared.f32 %f_x3, [%r_inA+84];
    ld.shared.f32 %f_x4, [%r_inA+88];
    ld.shared.f32 %f_x5, [%r_inA+92];
    ld.shared.f32 %f_b0, [%r_sbase+21612];
    ld.shared.f32 %f_b1, [%r_sbase+21616];
    ld.shared.f32 %f_b2, [%r_sbase+21620];
    fma.rn.f32 %f_acc0, %f_x0, %f_b0, %f_acc0;
